Voici un exemple de code en C qui utilise SDL pour créer un serpent simple :

```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

// Structure du serpent
typedef struct {
    int x, y;
    int taille;
    int direction;
    int score;
} Snake;

// Images du serpent
SDL_Texture* headTexture;
SDL_Texture* bodyTexture;

// Fonction pour charger les textures
void loadTextures(SDL_Renderer* renderer) {
    headTexture = IMG_LoadTexture(renderer, "head.png");
    bodyTexture = IMG_LoadTexture(renderer, "body.png");
}

// Fonction pour dessiner le serpent
void drawSnake(SDL_Renderer* renderer, Snake* snake) {
    SDL_Rect headRect = {snake->x, snake->y, 20, 20};
    SDL_Rect bodyRect = {snake->x - 20, snake->y, 20, 20};

    SDL_RenderCopy(renderer, headTexture, NULL, &headRect);
    for (int I = 0; I < snake->taille - 1; i++) {
        bodyRect.x += 20;
        SDL_RenderCopy(renderer, bodyTexture, NULL, &bodyRect);
    }
}

// Fonction pour gérer le mouvement du serpent
void moveSnake(Snake* snake, int direction) {
    switch (direction) {
        case SDL_SCANCODE_UP:
            snake->y -= 20;
            break;
        case SDL_SCANCODE_DOWN:
            snake->y += 20;
            break;
        case SDL_SCANCODE_LEFT:
            snake->x -= 20;
            break;
        case SDL_SCANCODE_RIGHT:
            snake->x += 20;
            break;
    }
}

// Fonction principale pour exécuter le jeu
int main(int argc, char** argv) {
    SDL_Init(SDL_INIT_VIDEO);
    SDL_Window* window = SDL_CreateWindow("Snake",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        640, 480, SDL_WINDOW_SHOWN);

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);

    Snake snake = {320, 240, 1, SDL_SCANCODE_RIGHT, 0};

    loadTextures(renderer);

    bool running = true;
    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            } else if (event.type == SDL_KEYDOWN) {
                if (snake.direction == SDL_SCANCODE_RIGHT || snake.direction == SDL_SCANCODE_LEFT) {
                    if (event.key.keysym.scancode != SDL_SCANCODE_UP && event.key.keysym.scancode != SDL_SCANCODE_DOWN) {
                        snake.direction = event.key.keysym.scancode;
                    }
                } else if (snake.direction == SDL_SCANCODE_UP || snake.direction == SDL_SCANCODE_DOWN) {
                    if (event.key.keysym.scancode != SDL_SCANCODE_LEFT && event.key.keysym.scancode != SDL_SCANCODE_RIGHT) {
                        snake.direction = event.key.keysym.scancode;
                    }
                }
            }
        }

        moveSnake(&snake, snake.direction);

        SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
        SDL_RenderClear(renderer);

        drawSnake(renderer, &snake);

        SDL_RenderPresent(renderer);
        SDL_Delay(10);
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
``` 

